import fs from 'fs/promises';
import path from 'path';
import { pathToFileURL } from 'url';
import { execFile, type ChildProcess } from 'child_process';
import { promisify } from 'util';
import { errnoCode } from '../utils/errnoCode';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import {
  GuidanceVerifierPackageSchema,
  GuidanceVerifierResultSchema,
  type GuidanceVerification,
  type GuidanceVerifierInput,
  type GuidanceVerifierRun,
} from '../types/guidance-verifier';
import { materializeTextFiles } from './retainedTextFiles';
import { selectedOperatingSystemServices } from './OperatingSystemServices';

interface RunInput {
  packet: GuidanceVerification;
  projectPath: string;
  target: Record<string, unknown>;
  runsDirectory: string;
  timeoutMs?: number;
  outputBytes?: number;
  signal?: AbortSignal;
}
interface OwnedProcess {
  pid: number;
  parentPid: number;
  groupId: number;
}
type RunReason = Extract<GuidanceVerifierRun, { execution: 'error' }>['reason'];
const TIMEOUT_MS = 120000;
const OUTPUT_BYTES = 1024 * 1024;
const RESULT_BYTES = 5 * 1024 * 1024;
const CLOSE_TIMEOUT_MS = 5000;
const PROCESS_POLL_MS = 20;
const PROCESS_SNAPSHOT_MS = 1000;
const READY_MESSAGE = 'rivet-verifier-ready';
const HOST_SOURCE = `import fs from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
const [inputPath, entrypoint, resultPath] = process.argv.slice(2);
setInterval(() => {}, 1000);
try {
  const input = JSON.parse(await fs.readFile(inputPath, 'utf8'));
  const { verify } = await import(pathToFileURL(entrypoint).href);
  if (typeof verify !== 'function') throw new Error('Package must export verify(input)');
  const result = await verify(input);
  await fs.writeFile(resultPath, JSON.stringify({ result }, (_key, value) => {
    if ((typeof value === 'number' && !Number.isFinite(value)) || ['function', 'symbol', 'bigint'].includes(typeof value)) throw new Error('Verifier results must contain finite JSON values');
    return value;
  }), { flag: 'wx', mode: 0o600 });
} catch (error) {
  console.error(error);
  await fs.writeFile(resultPath, JSON.stringify({ error: true }), { flag: 'wx', mode: 0o600 });
}
if (process.send) process.send('rivet-verifier-ready');
`;

const terminateDescendants = async (
  rootPid: number | undefined,
): Promise<void> => {
  if (rootPid === undefined || process.platform === 'win32') return;
  try {
    process.kill(-rootPid, 'SIGSTOP');
  } catch (error) {
    if (errnoCode(error) !== 'ESRCH') throw error;
  }
  const { stdout } = await promisify(execFile)(
    '/bin/ps',
    ['-axo', 'pid=,ppid=,pgid='],
    {
      timeout: PROCESS_SNAPSHOT_MS,
      killSignal: 'SIGKILL',
      maxBuffer: OUTPUT_BYTES,
      env: subprocessEnvironment('verifier'),
    },
  );
  const children = new Map<number, OwnedProcess[]>();
  const inherited: OwnedProcess[] = [];
  for (const line of stdout.split('\n')) {
    const fields = /^\s*(\d+)\s+(\d+)\s+(\d+)\s*$/.exec(line);
    if (!fields) continue;
    const entry = {
      pid: Number(fields[1]),
      parentPid: Number(fields[2]),
      groupId: Number(fields[3]),
    };
    if (entry.groupId === rootPid && entry.pid !== rootPid)
      inherited.push(entry);
    const siblings = children.get(entry.parentPid) ?? [];
    siblings.push(entry);
    children.set(entry.parentPid, siblings);
  }
  const descendants: OwnedProcess[] = [...inherited];
  const queue = [rootPid, ...inherited.map((entry) => entry.pid)];
  const visited = new Set(queue);
  for (const pid of queue) {
    for (const entry of children.get(pid) ?? []) {
      if (visited.has(entry.pid)) continue;
      visited.add(entry.pid);
      descendants.push(entry);
      queue.push(entry.pid);
    }
  }
  for (const entry of descendants.reverse()) {
    try {
      process.kill(
        entry.pid === entry.groupId ? -entry.pid : entry.pid,
        'SIGKILL',
      );
    } catch (error) {
      if (errnoCode(error) !== 'ESRCH') throw error;
    }
  }
  if (!descendants.length) return;
  const deadline = Date.now() + PROCESS_SNAPSHOT_MS;
  while (Date.now() < deadline) {
    let states: string;
    try {
      const result = await promisify(execFile)(
        '/bin/ps',
        [
          '-p',
          descendants.map((entry) => entry.pid).join(','),
          '-o',
          'pid=,stat=',
        ],
        {
          env: subprocessEnvironment('verifier'),
          timeout: Math.max(1, deadline - Date.now()),
          killSignal: 'SIGKILL',
          maxBuffer: OUTPUT_BYTES,
        },
      );
      states = result.stdout;
    } catch (error) {
      if ((error as { code?: unknown }).code === 1) return;
      throw error;
    }
    if (
      states
        .split('\n')
        .every((line) => !line.trim() || /^\s*\d+\s+Z/.test(line))
    )
      return;
    await new Promise((resolve) => setTimeout(resolve, PROCESS_POLL_MS));
  }
  throw new Error('Owned verifier descendants did not stop');
};

const waitForCleanup = async (completion: Promise<void>): Promise<void> => {
  let timer: NodeJS.Timeout | undefined;
  try {
    await Promise.race([
      completion,
      new Promise<never>((_, reject) => {
        timer = setTimeout(
          () => reject(new Error('Process cleanup did not finish')),
          CLOSE_TIMEOUT_MS,
        );
      }),
    ]);
  } finally {
    clearTimeout(timer);
  }
};

const supervise = async (args: {
  child: ChildProcess;
  runDirectory: string;
  timeoutMs: number;
  outputBytes: number;
  signal?: AbortSignal;
}): Promise<RunReason | undefined> => {
  const { child } = args;
  let diagnostics = Buffer.alloc(0);
  let outputSize = 0;
  let hasClosed = false;
  const closed = new Promise<void>((resolve) =>
    child.once('close', () => {
      hasClosed = true;
      resolve();
    }),
  );
  const reason = await new Promise<RunReason | undefined>((resolve) => {
    const timer = setTimeout(() => finish('timeout'), args.timeoutMs);
    const abort = (): void => finish('cancelled');
    let isSettled = false;
    const finish = (failure?: RunReason): void => {
      if (isSettled) return;
      isSettled = true;
      clearTimeout(timer);
      args.signal?.removeEventListener('abort', abort);
      resolve(failure);
    };
    const collect = (chunk: Buffer): void => {
      outputSize += chunk.length;
      diagnostics = Buffer.concat([
        diagnostics,
        chunk.subarray(0, Math.max(0, args.outputBytes - diagnostics.length)),
      ]);
      if (outputSize > args.outputBytes) finish('output_limit');
    };
    args.signal?.addEventListener('abort', abort, { once: true });
    if (args.signal?.aborted) abort();
    child.stdout?.on('data', collect);
    child.stderr?.on('data', collect);
    child.once('error', () => finish('process_failed'));
    child.once('exit', () => finish('process_failed'));
    child.on('message', (message) => {
      if (message === READY_MESSAGE) finish();
    });
  });
  try {
    let hasCleanupFailed = false;
    try {
      await terminateDescendants(child.pid);
    } catch {
      hasCleanupFailed = true;
    }
    try {
      await waitForCleanup(
        selectedOperatingSystemServices.projectProcesses.terminate(child, {
          isForceful: true,
          env: subprocessEnvironment('verifier'),
        }),
      );
    } catch {
      hasCleanupFailed = true;
      try {
        if (process.platform !== 'win32' && child.pid)
          process.kill(-child.pid, 'SIGKILL');
        else child.kill('SIGKILL');
      } catch (error) {
        if (errnoCode(error) !== 'ESRCH') throw error;
      }
    }
    if (!hasClosed) await waitForCleanup(closed);

    await fs.writeFile(
      path.join(args.runDirectory, 'diagnostics.txt'),
      diagnostics,
      { flag: 'wx', mode: 0o600 },
    );
    return hasCleanupFailed ? 'cleanup_failed' : reason;
  } catch {
    return 'cleanup_failed';
  }
};

const validateEvidence = async (
  directory: string,
  names: string[],
): Promise<void> => {
  const root = await fs.lstat(directory);
  if (!root.isDirectory() || root.isSymbolicLink())
    throw new Error('Unsafe evidence root');
  for (const name of names) {
    const segments = name.split('/');
    let location = directory;
    for (const [index, segment] of segments.entries()) {
      location = path.join(location, segment);
      const stat = await fs.lstat(location);
      if (
        stat.isSymbolicLink() ||
        (index < segments.length - 1
          ? !stat.isDirectory()
          : !stat.isFile() || stat.nlink !== 1)
      )
        throw new Error(
          'Evidence must be a regular file inside its run directory',
        );
    }
  }
};

const executeGuidanceVerifier = async (
  args: RunInput,
): Promise<GuidanceVerifierRun> => {
  const started = Date.now();
  let runDirectory = args.runsDirectory;
  let projectPath = args.projectPath;
  const verifier = {
    contextId: args.packet.source.id,
    sourceDigest: args.packet.sourceDigest,
  };
  const failed = (reason: RunReason): GuidanceVerifierRun => ({
    schemaVersion: 1,
    verifier,
    projectPath,
    execution: 'error',
    reason,
    runDirectory,
    durationMs: Date.now() - started,
  });
  try {
    if (args.packet.verifierState === 'missing')
      return failed('verifier_missing');
    if (args.packet.verifierState === 'stale') return failed('verifier_stale');
    if (!args.packet.verifier.package) return failed('package_required');
    await fs.mkdir(args.runsDirectory, { recursive: true, mode: 0o700 });
    runDirectory = await fs.mkdtemp(
      path.join(await fs.realpath(args.runsDirectory), 'run-'),
    );
    if (args.signal?.aborted) return failed('cancelled');
    const executable = GuidanceVerifierPackageSchema.parse(
      args.packet.verifier.package,
    );
    const packageDirectory = await materializeTextFiles({
      files: executable.files,
      directory: path.join(runDirectory, 'package'),
    });
    projectPath = await fs.realpath(args.projectPath);
    if (!(await fs.stat(projectPath)).isDirectory())
      return failed('setup_failed');
    const evidenceDirectory = path.join(runDirectory, 'evidence');
    await fs.mkdir(evidenceDirectory, { mode: 0o700 });
    const input: GuidanceVerifierInput = {
      source: args.packet.source,
      projectPath,
      target: args.target,
      evidenceDirectory,
      modules: {
        playwright: pathToFileURL(
          path.join(
            path.dirname(require.resolve('playwright-core/package.json')),
            'index.mjs',
          ),
        ).href,
      },
    };
    const inputPath = path.join(runDirectory, 'input.json');
    const resultPath = path.join(runDirectory, 'result.json');
    const hostPath = path.join(runDirectory, 'host.mjs');
    await fs.writeFile(inputPath, JSON.stringify(input), {
      flag: 'wx',
      mode: 0o600,
    });
    await fs.writeFile(hostPath, HOST_SOURCE, { flag: 'wx', mode: 0o600 });
    const child = selectedOperatingSystemServices.projectProcesses.start(
      {
        executable: process.execPath,
        args: [
          hostPath,
          inputPath,
          path.join(packageDirectory, executable.entrypoint),
          resultPath,
        ],
      },
      {
        cwd: projectPath,
        env: subprocessEnvironment('verifier'),
        shell: false,
        detached: process.platform !== 'win32',
        stdio: ['ignore', 'pipe', 'pipe', 'ipc'],
      },
    );
    const reason = await supervise({
      child,
      runDirectory,
      timeoutMs: args.timeoutMs ?? TIMEOUT_MS,
      outputBytes: args.outputBytes ?? OUTPUT_BYTES,
      signal: args.signal,
    });
    if (reason) return failed(reason);
    let result;
    try {
      const stat = await fs.lstat(resultPath);
      if (
        !stat.isFile() ||
        stat.isSymbolicLink() ||
        stat.nlink !== 1 ||
        stat.size > RESULT_BYTES
      )
        return failed('invalid_result');
      const raw = JSON.parse(await fs.readFile(resultPath, 'utf8'));
      if (raw.error) return failed('process_failed');
      result = GuidanceVerifierResultSchema.parse(raw.result);
    } catch {
      return failed('invalid_result');
    }
    try {
      await validateEvidence(
        evidenceDirectory,
        result.checks.flatMap((check) =>
          check.evidence.map((artifact) => artifact.path),
        ),
      );
    } catch {
      return failed('invalid_evidence');
    }
    let status: 'pass' | 'fail' | 'blocked' = 'pass';
    if (result.checks.some((check) => check.status === 'fail')) status = 'fail';
    else if (result.checks.some((check) => check.status === 'blocked'))
      status = 'blocked';
    return {
      schemaVersion: 1,
      verifier,
      projectPath,
      execution: 'completed',
      status,
      checks: result.checks,
      runDirectory,
      durationMs: Date.now() - started,
    };
  } catch {
    return failed('setup_failed');
  }
};

let activeVerificationCount = 0;
export const hasActiveGuidanceVerifications = (): boolean =>
  activeVerificationCount > 0;
export const runGuidanceVerifier = async (
  args: RunInput,
): Promise<GuidanceVerifierRun> => {
  activeVerificationCount += 1;
  try {
    return await executeGuidanceVerifier(args);
  } finally {
    activeVerificationCount -= 1;
  }
};
